javascript:(async()=>{ const ARCH='https://moisesms1999-dev.github.io/archive-/'; const $=(t,p={},...k)=>{const e=document.createElement(t);Object.assign(e,p);if(p.style)e.setAttribute('style',p.style);k.flat().forEach(c=>e.append(c));return e;}; const html=document.documentElement.innerHTML; const TOK=(html.match(/"API_TOKEN":"([^"]+)"/)||[])[1]; const CSRF=(html.match(/"csrfToken":"([^"]+)"/)||[])[1]; const api=async(path,opts={})=>{ if(window.tumblr&&typeof window.tumblr.apiFetch==='function'){ const o={method:opts.method||'GET'};if(opts.body)o.body=opts.body; try{return await window.tumblr.apiFetch('/v2'+path,o);}catch(e){return {error:String(e&&(e.message||e)),body:e&&e.body};} } const r=await fetch('/api/v2'+path,{method:opts.method||'GET',credentials:'include',headers:{'Authorization':'Bearer '+TOK,'Content-Type':'application/json','X-Version':'redpop/3/0//redpop/','X-CSRF':CSRF||''},body:opts.body?JSON.stringify(opts.body):undefined}); let j=null;try{j=await r.json();}catch(e){}return j&&r.ok?j:{error:'HTTP '+r.status,detail:j}; }; const box=$('div',{id:'rnc',style:'position:fixed;inset:0;z-index:2147483647;background:#1a120b;color:#ffd9b0;font:16px/1.4 system-ui,sans-serif;overflow:auto;padding:16px 14px 40px'}); const log=$('div',{style:'font-size:13px;color:#e7b98a;white-space:pre-wrap;max-height:34vh;overflow:auto;margin-top:10px'}); const st=$('div',{style:'color:#9be59b;min-height:1.3em;margin:8px 0'}); const close=$('button',{textContent:'✕ Cerrar',style:'position:absolute;top:10px;right:12px;background:#5a3a1e;color:#ffd9b0;border:0;border-radius:10px;padding:8px 12px;font-weight:700'}); close.onclick=()=>box.remove(); box.append(close,$('h2',{textContent:'🍪 Renacer',style:'color:#ff9a3c;margin:0 0 4px'}),$('div',{textContent:'modo: '+((window.tumblr&&typeof window.tumblr.apiFetch==='function')?'interno':'alternativo'),style:'font-size:11px;color:#a58a6a'}),$('p',{textContent:'Publica en el blog que elijas. Tandas de 5, 10 segundos entre posts.',style:'color:#f3c99a;margin:0 0 12px'})); document.body.append(box); let blogs=[]; const u=await api('/user/info'); const R=u&&(u.response||u); if(R&&R.user&&R.user.blogs)blogs=R.user.blogs.map(b=>({name:b.name,uuid:b.uuid})); else{box.append($('p',{textContent:'No pude leer tus blogs: '+JSON.stringify(u).slice(0,200)+' — ¿estás en tumblr.com con la sesión iniciada?'}));} const sel=$('select',{style:'width:100%;padding:11px;border-radius:10px;background:#1a120b;color:#ffd9b0;border:1px solid #5a3a1e;margin-bottom:12px'}); blogs.forEach(b=>sel.append($('option',{value:b.name,textContent:b.name}))); box.append(sel); const fbox=$('div',{style:'background:#2a1a0e;border:1px solid #5a3a1e;border-radius:12px;padding:10px;margin:0 0 12px'}); const fst=$('div',{style:'color:#9be59b;font-size:14px;min-height:1.2em;margin-top:6px'}); const flog=$('div',{style:'font-size:12px;color:#e7b98a;white-space:pre-wrap;max-height:18vh;overflow:auto'}); const bstyle='display:block;width:100%;text-align:left;background:#5a3a1e;color:#ffd9b0;border:0;border-radius:10px;padding:11px;margin:6px 0 0;font-weight:700'; const bF=$('button',{textContent:'👥 Seguir a todos mis seguidores',style:bstyle}); const bL=$('button',{textContent:'📋 Seguir a mi lista fija',style:bstyle}); const sp=$('select',{style:'width:100%;padding:9px;border-radius:10px;background:#1a120b;color:#ffd9b0;border:1px solid #5a3a1e;margin-top:6px'});sp.append($('option',{value:'n',textContent:'Velocidad normal (uno cada 2,5 a 5 s)'}),$('option',{value:'f',textContent:'Rápido (uno cada 0,8 a 1,6 s)'})); fbox.append($('b',{textContent:'Seguidores',style:'color:#ffb066'}),sp,bF,bL,fst,flog);box.append(fbox); const nap=()=>new Promise(r=>setTimeout(r,sp.value==='f'?800+Math.random()*800:2500+Math.random()*2500)); async function followAll(names,label){ bF.disabled=bL.disabled=true;let ok=0,n=0; for(const nm of names){n++;fst.textContent=label+': '+n+' de '+names.length+' ('+nm+')'; const r=await api('/user/follow',{method:'POST',body:{url:'https://'+nm+'.tumblr.com'}}); if(r&&!r.error&&!(r.meta&&r.meta.status>=400)){ok++;flog.textContent+='✓ '+nm+'\n';}else flog.textContent+='✗ '+nm+'\n'; flog.scrollTop=1e9;await nap();} fst.textContent=label+': hecho, '+ok+' seguidos de '+names.length+'.';bF.disabled=bL.disabled=false; } bF.onclick=async()=>{const blog=sel.value;fst.textContent='Leyendo seguidores de '+blog+'…';let users=[],off=0,total=0; for(let k=0;k<100;k++){const r=await api('/blog/'+blog+'/followers?limit=20&offset='+off);const R=r&&(r.response||r); if(!R||!R.users){fst.textContent='No pude leer los seguidores: '+JSON.stringify(r).slice(0,150);return;} total=R.total_users||0;users=users.concat(R.users);if(R.users.length<20||users.length>=total)break;off+=20;} const todo=users.filter(x=>!x.following).map(x=>x.name); flog.textContent='Seguidores: '+total+'. Por seguir: '+todo.length+'\n'; if(!todo.length){fst.textContent='Ya los sigues a todos.';return;} followAll(todo,'Seguidores');}; bL.onclick=async()=>{fst.textContent='Leyendo la lista…';let t='';try{t=await (await fetch(ARCH+'lista.txt?'+Date.now())).text();}catch(e){} const L=[...new Set(t.split(/\r?\n/).map(x=>x.trim().toLowerCase().replace(/^@/,'')).filter(Boolean))]; if(!L.length){fst.textContent='La lista está vacía.';return;} followAll(L,'Lista fija');}; const list=$('div');box.append(list,st,log); function inline(node,acc){ for(const n of node.childNodes){ if(n.nodeType===3){acc.text+=n.nodeValue;continue;} if(n.nodeType!==1)continue; const tag=n.tagName,s=acc.text.length; if(tag==='BR'){acc.text+='\n';continue;} inline(n,acc);const e=acc.text.length;if(e<=s)continue; if(tag==='B'||tag==='STRONG')acc.fmt.push({start:s,end:e,type:'bold'}); else if(tag==='I'||tag==='EM')acc.fmt.push({start:s,end:e,type:'italic'}); else if(tag==='A'&&n.getAttribute('href'))acc.fmt.push({start:s,end:e,type:'link',url:n.getAttribute('href')}); } return acc; } function textBlocks(el,subtype){ const a=inline(el,{text:'',fmt:[]});const t=a.text.replace(/\s+$/,'');if(!t.trim())return []; const out=[]; for(let i=0;i<t.length;i+=4000){const piece=t.slice(i,i+4000);const b={type:'text',text:piece}; const f=a.fmt.filter(x=>x.start<i+4000&&x.end>i).map(x=>Object.assign({},x,{start:Math.max(0,x.start-i),end:Math.min(piece.length,x.end-i)})); if(f.length)b.formatting=f;if(subtype)b.subtype=subtype;out.push(b);} return out; } function toNPF(h){ const doc=new DOMParser().parseFromString('<div>'+h+'</div>','text/html');const root=doc.body.firstChild;const C=[]; for(const el of root.children){ const tag=el.tagName; if(tag==='FIGURE'){const url=el.getAttribute('data-url')||((el.querySelector('iframe')||{}).src||'');if(url)C.push({type:'video',provider:'youtube',url:url.replace('/embed/','/watch?v=').replace(/\?feature=oembed/,'')});continue;} const as=el.querySelectorAll?el.querySelectorAll('a'):[]; if(tag==='P'&&as.length===1&&!el.querySelector('img')&&el.textContent.trim()===as[0].textContent.trim()&&/^https?:/.test(as[0].getAttribute('href')||'')){C.push({type:'link',url:as[0].getAttribute('href'),title:as[0].textContent.trim()});continue;} const img=el.tagName==='IMG'?el:el.querySelector('img'); if(img&&!el.textContent.trim()){C.push({type:'image',media:[{url:img.getAttribute('src')}]});continue;} if(tag==='BLOCKQUOTE'){for(const c of (el.children.length?el.children:[el]))C.push(...textBlocks(c,'indented'));continue;} if(tag==='UL'||tag==='OL'){for(const li of el.children)C.push(...textBlocks(li,tag==='UL'?'unordered-list-item':'ordered-list-item'));continue;} C.push(...textBlocks(el)); } return C; } let items=[]; try{items=await (await fetch(ARCH+'index.json?'+Date.now())).json();}catch(e){list.append($('p',{textContent:'No pude leer el archivo.'}));} for(const it of items){ const b=$('button',{textContent:it.title,style:'display:block;width:100%;text-align:left;background:#3a2412;color:#ffd9b0;border:0;border-radius:10px;padding:12px;margin:0 0 8px;font-weight:700'}); b.onclick=async()=>{st.textContent='Leyendo '+it.title+'…'; const h=await (await fetch(ARCH+it.path+'?'+Date.now())).text(); const m=h.match(/const (?:D|P)=(\[[\s\S]*?\]);\s*const TAGS=("(?:[^"\\]|\\.)*")/); if(!m){st.textContent='Esa página no tiene posts.';return;} const base=new URL(it.path,ARCH).href.replace(/[^/]*$/,''); const D=JSON.parse(m[1]).map(x=>x.split('MEDIA/').join(base+'media/')); const TAGS=JSON.parse(m[2]).split(',').map(s=>s.trim()).filter(Boolean); const labs={};let lm;const lre=/data-i="(\d+)"[^>]*>(?:<span[^>]*>[^<]*<\/span>)?<span class="t">([^<]*)<\/span>/g; while((lm=lre.exec(h)))labs[+lm[1]]=lm[2]; showPosts(it,D,TAGS,labs);st.textContent=''; }; list.append(b); } function showPosts(it,D,TAGS,labs){ const title=it.title;list.innerHTML='';list.append($('h3',{textContent:title,style:'color:#ffb066;margin:4px 0 8px'})); const chk=$('input',{type:'checkbox',checked:!!it.chain});const cl=$('label',{style:'display:flex;gap:8px;align-items:center;margin:0 0 10px;color:#ffb066;font-weight:700'});cl.append(chk,$('span',{textContent:'⛓ En cadena: cada post rebloguea el anterior, desde el marcado en adelante'}));list.append(cl); const KEY=()=>'rnc_chain_'+it.path+'_'+sel.value; const checks=[]; D.forEach((d,i)=>{const row=$('label',{style:'display:flex;gap:8px;align-items:flex-start;margin:0 0 8px;font-size:14px'}); const c=$('input',{type:'checkbox',checked:true});c.dataset.i=i;checks.push(c); row.append(c,$('span',{textContent:(labs[i]||('Post '+(i+1)))+' · '+(d.match(/<img /g)||[]).length+' img'}));list.append(row);}); const pub=$('button',{textContent:'Publicar los marcados (tanda de 5)',style:'display:block;width:100%;background:#ff9a3c;color:#1a120b;border:0;border-radius:12px;padding:15px;font-weight:800;margin:8px 0'}); const chain={}; pub.onclick=async()=>{ const blog=sel.value; let picks; if(chk.checked){const first=checks.findIndex(c=>c.checked&&!c.disabled);if(first<0){st.textContent='Marca desde cuál empezar.';return;}picks=checks.slice(first).filter(c=>!c.disabled).slice(0,5);} else picks=checks.filter(c=>c.checked&&!c.disabled).slice(0,5); if(!picks.length){st.textContent='No hay nada marcado.';return;} pub.disabled=true;let ok=0; let uuid=null;if(chk.checked){const bi=await api('/blog/'+blog+'/info');const BI=bi&&(bi.response||bi);uuid=BI&&BI.blog&&BI.blog.uuid;} let prev=null;try{prev=JSON.parse(localStorage.getItem(KEY())||'null');}catch(e){} const why=x=>{const e=(x&&x.body&&x.body.errors&&x.body.errors[0])||{};return (e.code||'')+' '+(e.detail||e.title||x&&x.error||'');}; for(let n=0;n<picks.length;n++){ const i=+picks[n].dataset.i;st.textContent='Publicando '+(n+1)+' de '+picks.length+'…'; const content=toNPF(D[i]);const tags=TAGS.slice(0,30).join(','); const isRe=chk.checked&&prev&&prev.next===i&&uuid; const body={content,tags,state:'published'}; if(isRe){body.parent_tumblelog_uuid=uuid;body.parent_post_id=prev.id;body.reblog_key=prev.key;} let r=await api('/blog/'+blog+'/posts',{method:'POST',body}); if(r&&r.error){log.textContent+=' · nativo: '+why(r)+'\n'; const x=isRe?await api('/blog/'+blog+'/post/reblog',{method:'POST',body:{id:prev.id,reblog_key:prev.key,comment:D[i],tags}}) :await api('/blog/'+blog+'/post',{method:'POST',body:{type:'text',format:'html',body:D[i],tags}}); if(x&&!x.error){r=x;log.textContent+=' (como HTML, igual que pegarlo)\n';}else log.textContent+=' · HTML: '+why(x)+'\n';} const RR=r&&(r.response||r);const id=RR&&(RR.id_string||RR.id); if(id){ok++;log.textContent+='✓ '+(labs[i]||('Post '+(i+1)))+(isRe?' (reblog)':'')+' → '+id+'\n';picks[n].checked=false;picks[n].disabled=true; if(chk.checked){const g=await api('/blog/'+blog+'/posts/'+id);const P=g&&(g.response||g);const key=P&&(P.reblog_key||(P.posts&&P.posts[0]&&P.posts[0].reblog_key)); prev={id:String(id),key:key,next:i+1};try{localStorage.setItem(KEY(),JSON.stringify(prev));}catch(e){} if(checks[i+1]&&!checks[i+1].disabled)checks[i+1].checked=true;}} else{log.textContent+='✗ '+(labs[i]||('Post '+(i+1)))+' · '+why(r)+'\n';break;} log.scrollTop=1e9; if(n<picks.length-1)for(let t=10;t>0;t--){st.textContent='Siguiente en '+t+' s…';await new Promise(r=>setTimeout(r,1000));} } const left=checks.filter(c=>!c.disabled).length-(chk.checked?0:0); st.textContent='Tanda hecha: '+ok+' de '+picks.length+'.'+(chk.checked?' La cadena sigue donde lo dejaste: vuelve a pulsar para la siguiente tanda.':'');pub.disabled=false; }; list.append(pub); } })();